package net.kasax.raft.world.biome;

import net.kasax.raft.Raft;
import net.minecraft.core.registries.Registries;
import net.minecraft.resources.ResourceKey;
import net.minecraft.tags.TagKey;
import net.minecraft.world.level.biome.Biome;

/**
 * Keys of the biomes of the raft dimension ("The Endless Sea"). The biomes themselves are data files generated by
 * tools/content/world (module "world", see docs/design/beachcraft3.md section 4.2).
 */
public final class ModBiomes {
    public static final ResourceKey<Biome> RAFT_OCEAN_BIOME = key("raft_ocean_biome");
    public static final ResourceKey<Biome> KELP_FOREST = key("kelp_forest");
    public static final ResourceKey<Biome> CORAL_SHALLOWS = key("coral_shallows");
    public static final ResourceKey<Biome> GLOWING_LAGOON = key("glowing_lagoon");
    public static final ResourceKey<Biome> DROWNED_SHELF = key("drowned_shelf");
    public static final ResourceKey<Biome> ABYSSAL_TRENCH = key("abyssal_trench");
    public static final ResourceKey<Biome> WRECK_GRAVEYARD = key("wreck_graveyard");
    public static final ResourceKey<Biome> FROST_FLOES = key("frost_floes");
    public static final ResourceKey<Biome> PALM_ISLE = key("palm_isle");
    public static final ResourceKey<Biome> JUNGLE_ISLE = key("jungle_isle");
    public static final ResourceKey<Biome> MANGROVE_ISLE = key("mangrove_isle");
    public static final ResourceKey<Biome> VOLCANIC_ISLE = key("volcanic_isle");

    /** All 12 biomes of the raft dimension. */
    public static final TagKey<Biome> IS_RAFT_DIMENSION = tag("is_raft_dimension");
    public static final TagKey<Biome> IS_ISLAND = tag("is_island");
    public static final TagKey<Biome> IS_SHALLOW = tag("is_shallow");
    public static final TagKey<Biome> IS_DEEP = tag("is_deep");

    private ModBiomes() {
    }

    private static ResourceKey<Biome> key(String name) {
        return ResourceKey.create(Registries.BIOME, Raft.id(name));
    }

    private static TagKey<Biome> tag(String name) {
        return TagKey.create(Registries.BIOME, Raft.id(name));
    }
}
